            const done = i < curIdx, now = i === curIdx && can;
            return '<div style="padding:10px 8px;border-radius:14px;text-align:center;background:' + (now ? 'radial-gradient(circle at 50% 0%,rgba(251,191,36,.32),rgba(20,14,28,.95))' : 'rgba(255,255,255,.04)') + ';border:1.5px solid ' + (now ? '#fde047' : done ? 'rgba(74,222,128,.5)' : 'rgba(218,174,86,.24)') + ';opacity:' + (done ? '.62' : '1') + '">'
                + '<small style="display:block;font-size:10px;font-weight:900;color:' + (now ? '#fde047' : '#bfb29d') + '">DIA ' + it.d + '</small>'
