        o += '<path d="M-40,2060 C260,1940 480,2150 800,2030 S1300,1960 1640,2080" fill="none" stroke="#5ff0d0" stroke-width="46" stroke-linecap="round" opacity=".10"/><path d="M-40,2130 C300,2030 520,2220 840,2100 S1320,2060 1640,2160" fill="none" stroke="#a78bfa" stroke-width="34" stroke-linecap="round" opacity=".11"/><path d="M-40,1990 C220,1900 520,2060 860,1960 S1340,1900 1640,2000" fill="none" stroke="#7fe3ff" stroke-width="24" stroke-linecap="round" opacity=".12"/>';
        o += warMapRange(2000, 260, 7, 11, '#2d7fa6', '#f2fbff', 0.30) + warMapRange(2140, 300, 6, 12, '#195575', '#e6f6ff', 0.55) + warMapRange(2290, 230, 8, 13, '#0f3a55', '#d4efff', 0.85);
        o += '<ellipse cx="540" cy="2330" rx="250" ry="38" fill="#bfeaff" opacity=".26"/><ellipse cx="540" cy="2326" rx="220" ry="26" fill="#e9fbff" opacity=".18"/>';
        o += warMapCloud(260, 1700, 1.3, '#2a1f56', .55) + warMapCloud(1180, 1610, 1.5, '#2e2260', .5) + warMapCloud(760, 1850, 1.1, '#3a2c70', .42) + warMapCloud(1380, 1860, 1.0, '#2a1f56', .5) + warMapCloud(120, 1400, 1.1, '#241a4a', .5);
        for (let i = 0; i < 14; i++) { const x = 60 + R() * 1480, y = 1300 + R() * 520; o += '<line x1="' + Math.round(x) + '" y1="' + Math.round(y) + '" x2="' + Math.round(x - 16) + '" y2="' + Math.round(y + 70) + '" stroke="#cdb8ff" stroke-width="2.4" stroke-linecap="round" opacity=".22"/>'; }
        let crack = ''; for (let c = 0; c < 9; c++) { let x = 60 + R() * 1480, y = 360 + R() * 900, d = 'M' + Math.round(x) + ',' + Math.round(y); for (let k = 0; k < 6; k++) { x += (R() - 0.5) * 120; y += 30 + R() * 60; d += ' L' + Math.round(x) + ',' + Math.round(y); } crack += '<path d="' + d + '" fill="none" stroke="#ff5a3c" stroke-width="5" stroke-linejoin="round" opacity=".22"/><path d="' + d + '" fill="none" stroke="#ffb067" stroke-width="2" stroke-linejoin="round" opacity=".4"/>'; }
        o += crack;
