        for (let i = 0; i < 46; i++) { const x = R() * 1600, y = 260 + R() * 1000; o += '<circle cx="' + Math.round(x) + '" cy="' + Math.round(y) + '" r="' + (1.6 + R() * 3).toFixed(1) + '" fill="' + (i % 3 ? '#ff9a4a' : '#ffd27a') + '" opacity="' + (0.35 + R() * 0.4).toFixed(2) + '"/>'; }
        o += warMapRange(1040, 220, 9, 14, '#2a0b12', '', 0.55);
