        pinsDom += `<div class="wm-chest-node${w.final3 ? ' got' : ''}" style="left:${(800 / 1600) * 100}%;top:${(250 / 3000) * 100}%"><span style="font-size:24px;line-height:1">${w.final3 ? '✅' : '🥚'}</span><div><b>Ovo do Cosmos (Lendário)</b><small>+6.000 cristais · +3.000 ouro · fase 60</small></div></div>`;
