            pinsDom += `<button type="button" class="wm-pin${S.boss ? ' boss' : ''}${lock ? ' lock' : ''}${done ? ' done' : ''}${isCur ? ' cur' : ''}" data-cl="zoo-war-stage" data-i="${i}" title="${S.n}" aria-label="Fase ${i + 1}: ${S.n}${lock ? ', bloqueada' : ''}" style="left:${(pt.x / 1600) * 100}%;top:${(pt.y / 3000) * 100}%;--rc:${R.col}">`
