        const gear = (x, y, r) => `<g transform="translate(${x},${y})" opacity=".5"><circle r="${r}" fill="none" stroke="#9fb4d0" stroke-width="10" stroke-dasharray="14 10"/><circle r="${r * 0.55}" fill="#26324a" stroke="#9fb4d0" stroke-width="4"/></g>`;
