        const CARD = 'background:rgba(40,21,9,.82)!important;border:3px solid #2b1608!important;border-radius:16px!important;box-shadow:inset 0 2px 0 #ffffff22,0 3px 0 #00000066!important;color:#ffeccb!important;font-family:' + F + '!important';
        const TITLE = 'color:#ffd44d!important;font-family:' + F + '!important;font-weight:400!important;text-shadow:' + OUT(INK, 2) + '!important;letter-spacing:.03em';
        const R = [];
        R.push('.cl-ao,.cl-wfg,.cl-pick,.cl-wm,.cl-wr,.cl-wf .wf-pause,.cl-wf .wf-bn,.cl-wf .wf-msg{font-family:' + F + '}');
        R.push('html body .cl-ao header,html body .cl-wfg>header,html body .cl-wm .wm-hud-top{' + WOOD + ';border-width:0 0 4px 0!important;border-style:solid!important}');
        R.push('html body .cl-ao header b,html body .cl-wfg>header b,html body .cl-wm .wm-brand h2,html body .cl-pick h2,html body .cl-ao h4{' + TITLE + '}');
        R.push('html body .cl-wm .wm-brand h2{font-size:26px!important}html body .cl-ao h4{font-size:14px!important;opacity:1!important}html body .cl-wm .wm-brand small{color:#ffe9a6!important;font-family:' + F + '!important;text-shadow:' + OUT(INK, 1) + '!important}html body .cl-wm .wm-brand span{color:#ffeccb!important;font-family:' + F + '!important}');
