        R.push('html body .cl-wfg .wfg-mode button.on,html body .cl-wfg .wfg-seg button.on,html body .cl-wfg .wfg-ptab.on{background:linear-gradient(#ffe36b,#f29a12)!important;color:#3a1a05!important;text-shadow:0 1px 0 #fff8!important;border-color:#6e3508!important}');
        R.push('html body .cl-ao .ao-go,html body .cl-wfg .wfg-go,html body .cl-ao .ao-res .ao-go,html body .cl-wf .wf-pause .wp-go,html body .cl-wr .wp-go{' + GOLD + ';font-size:17px!important}html body .cl-ao .ao-go[disabled],html body .cl-wfg .wfg-go[disabled]{filter:grayscale(.9) brightness(.8);opacity:.7}');
