            const r = hc.getBoundingClientRect();
            const px = Math.max(0, Math.min(1, (ev.clientX - r.left) / Math.max(1, r.width)));
            const py = Math.max(0, Math.min(1, (ev.clientY - r.top) / Math.max(1, r.height)));
