                const ready = eg.el >= eg.tot, rem = Math.max(0, eg.tot - eg.el), p = Math.max(0, Math.min(1, eg.el / Math.max(1, eg.tot)));
                const st = ready ? 4 : (p >= 0.7 ? 3 : p >= 0.35 ? 2 : 1);
