            can = have >= inf.cost && !cd && (z.eggs || []).length < ZARENA_INC;
            costTxt = ' (' + inf.cost + ' 🪙)';
            /* Chances visuais aproximadas e dica inteligente de dragões faltantes no Álbum */
            const maxRk = Math.min(4, Math.max(spA.rk, spB.rk) + 1), minRk = Math.min(3, Math.max(0, Math.min(spA.rk, spB.rk)));
            const oddsChips = [minRk, Math.min(4, minRk + 1), maxRk].filter((v, i, arr) => arr.indexOf(v) === i).map(q =>
                '<span style="--rc:' + ZR[q].col + '">' + ZR[q].n + (q === 4 ? ' (raro!)' : '') + '</span>'
            ).join('');
            const els = [spA.el, spB.el];
