            + [4, 3, 2, 1, 0].map(q => { const n = allAdults.filter(a => (zsp(a.sp).rk | 0) === q).length; return n ? '<button type="button" class="ao-rfb' + (rkF === q ? ' on' : '') + '" data-ao="rk" data-rk="' + q + '" style="--rc:' + ZR[q].col + '">' + ZR[q].n + ' (' + n + ')</button>' : ''; }).join('') + '</div>';
        const chips = adults.map(a => { const sp = zsp(a.sp), cd = (a.cd || 0) > 0, idx = ZOO.arSel.indexOf(a.id), on = idx >= 0; const tag = on ? '<span class="dk-pick-tag">' + (idx === 0 ? 'PAI A' : 'PAI B') + '</span>' : (cd ? '<span class="dk-badge-corner">⏳</span>' : ''); return '<button type="button" class="ao-chip cf-wrap' + (on ? ' on' : '') + (cd ? ' off' : '') + '" data-ao="pick" data-id="' + a.id + '" style="--rc:' + (ZR[sp.rk] || ZR[0]).col + '">' + clArenaCardHTML(sp, zAL(a), zStar(a), clArenaImg(a.sp, '', bud), { badge: tag }) + '</button>'; }).join('') || '<span style="font-size:12px;opacity:.8">Nenhum dragão adulto nesta raridade.</span>';
        let res = ''; if (ZOO.arRes) { const r = ZOO.arRes, sp = r.sp; res = '<div class="ao-res"><div><div style="font-size:12px;opacity:.8">' + (r.first ? 'NOVO NO LIVRO!' : 'Nasceu') + '</div>' + clArenaImg(sp.id, '', { n: 1 }) + '<h3 style="margin:6px 0">' + esc(sp.n) + '</h3><div style="color:' + (ZR[sp.rk] || ZR[0]).col + ';font-weight:800">' + (ZR[sp.rk] || ZR[0]).n + '</div><button type="button" class="ao-go" style="margin-top:14px;width:100%" data-ao="res-x">Legal!</button></div></div>'; }
        const nEggs = Math.min(ZARENA_INC, (z.eggs || []).length);
