        if (!document.getElementById('cl-pick-css')) { const st = document.createElement('style'); st.id = 'cl-pick-css'; st.textContent = '.cl-pick{position:absolute;inset:0;z-index:99990;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:16px;background:linear-gradient(#0a0712b8,#0a0712b8),radial-gradient(circle at 50% 42%,#1b123066,#07050cee 88%),#0a0712 url(./assets/colony/arena_menu.jpg?v=4) center/cover no-repeat;color:#fff4dc;font-family:system-ui}.cl-pick>*{animation:clPickIn .4s cubic-bezier(.2,.9,.3,1) both}@keyframes clPickIn{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:none}}.cl-pick h2{margin:0;font:700 clamp(20px,5vh,30px) Georgia,serif;letter-spacing:.02em}.cl-pick-row{display:flex;gap:clamp(12px,3vw,28px);width:min(720px,96%);justify-content:center}.cl-pick button{flex:1 1 0;max-width:330px;min-height:clamp(120px,38vh,210px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:12px;border-radius:20px;border:3px solid var(--c);background:linear-gradient(160deg,var(--b1),var(--b2));color:#fff4dc;font:inherit;cursor:pointer;box-shadow:0 8px 26px #000a,inset 0 1px #fff3;touch-action:manipulation;transition:transform .15s}.cl-pick button:active{transform:scale(.97)}.cl-pick button b{font:800 clamp(18px,4.6vh,26px) system-ui}.cl-pick button i{font:normal 12px/1.35 system-ui;opacity:.85;max-width:210px;text-align:center}.cl-pick button em{font-style:normal;font-size:clamp(38px,11vh,64px);line-height:1}.cl-pick .col{--c:#7fe3a0;--b1:#1c4a2c;--b2:#0e2a1a}.cl-pick .def{--c:#ffb34a;--b1:#5a3418;--b2:#2a1608}'; document.head.appendChild(st); }
        const d = document.createElement('div'); d.className = 'cl-pick'; d.setAttribute('role', 'dialog'); d.setAttribute('aria-label', 'Escolha entre Colônia e Arena');
        d.innerHTML = '<h2>Para onde vamos?</h2><div class="cl-pick-row"><button type="button" class="col" data-pk="col"><em>🏰</em><b>Colônia</b><i>Sua base: construir, produzir e cuidar dos dragões</i></button><button type="button" class="def" data-pk="def"><em>⚔️</em><b>Arena</b><i>Fases, chefes, runas e a forja</i></button></div>';
