        d.addEventListener('click', e => { const b = e.target.closest('[data-pk]'); if (!b) return; e.stopPropagation(); const def = b.dataset.pk === 'def'; d.remove(); if (ZOO.modal === 'colony-war') ZOO.modal = null; try { CL3.need = true; } catch (er) {} if (def) { try { clArenaHome(); } catch (er) {} } });
        CL.root.appendChild(d); ZOO.modal = 'colony-war';   /* com a escolha na tela a colônia NÃO é desenhada por trás (antes ficava visível e gastava a placa de vídeo) */
