        g.fillStyle = '#fff'; g.font = 'bold 70px "Lilita One", Arial, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.shadowColor = col; g.shadowBlur = 10; g.fillText(String(n), 64, 70);
