    function warBossSfx(kind) {
        try {
            if (WARV.muted) return;
            const ctx = warAudioCtx(); if (!ctx) return;
            if (ctx.state === 'suspended') { try { ctx.resume(); } catch (e) {} }
            const now = ctx.currentTime;
            if (kind === 'enter') {
                /* Entrada do Chefão: trompa grave de guerra + rugido sísmico */
                const g = ctx.createGain(); g.gain.setValueAtTime(0.001, now); g.gain.linearRampToValueAtTime(0.36, now + 0.06); g.gain.exponentialRampToValueAtTime(0.0001, now + 1.55); g.connect(ctx.destination);
                const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.setValueAtTime(420, now); lp.frequency.exponentialRampToValueAtTime(110, now + 1.4); lp.connect(g);
                const o1 = ctx.createOscillator(), o2 = ctx.createOscillator();
                o1.type = 'sawtooth'; o1.frequency.setValueAtTime(76, now); o1.frequency.exponentialRampToValueAtTime(48, now + 1.35);
                o2.type = 'sine'; o2.frequency.setValueAtTime(38, now); o2.frequency.exponentialRampToValueAtTime(24, now + 1.4);
                o1.connect(lp); o2.connect(g); o1.start(now); o2.start(now); o1.stop(now + 1.6); o2.stop(now + 1.6);
                const nb = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 0.9), ctx.sampleRate), nd = nb.getChannelData(0);
                for (let i = 0; i < nd.length; i++) nd[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / nd.length, 1.4);
                const ns = ctx.createBufferSource(); ns.buffer = nb;
                const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.setValueAtTime(260, now); bp.frequency.exponentialRampToValueAtTime(95, now + 0.85); bp.Q.value = 1.6;
                const ng = ctx.createGain(); ng.gain.setValueAtTime(0.24, now); ng.gain.exponentialRampToValueAtTime(0.0001, now + 0.9);
                ns.connect(bp); bp.connect(ng); ng.connect(ctx.destination); ns.start(now);
            } else if (kind === 'step') {
                /* Pisada pesada do Chefão (audível em Mac e tablet: corpo 190→54Hz + sub-grave + estalo de pedra) */
                const pv = 0.92 + Math.random() * 0.16;
                const g = ctx.createGain(); g.gain.setValueAtTime(0.001, now); g.gain.linearRampToValueAtTime(0.46, now + 0.012); g.gain.exponentialRampToValueAtTime(0.0001, now + 0.42); g.connect(ctx.destination);
                const o1 = ctx.createOscillator(), o2 = ctx.createOscillator();
                o1.type = 'triangle'; o1.frequency.setValueAtTime(190 * pv, now); o1.frequency.exponentialRampToValueAtTime(52 * pv, now + 0.24);
                o2.type = 'sine'; o2.frequency.setValueAtTime(86 * pv, now); o2.frequency.exponentialRampToValueAtTime(30 * pv, now + 0.36);
                o1.connect(g); o2.connect(g); o1.start(now); o2.start(now); o1.stop(now + 0.44); o2.stop(now + 0.44);
                const nb = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 0.22), ctx.sampleRate), nd = nb.getChannelData(0);
                for (let i = 0; i < nd.length; i++) nd[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / nd.length, 1.8);
                const ns = ctx.createBufferSource(); ns.buffer = nb;
                const lf = ctx.createBiquadFilter(); lf.type = 'lowpass'; lf.frequency.setValueAtTime(780, now); lf.frequency.exponentialRampToValueAtTime(180, now + 0.20);
                const ng = ctx.createGain(); ng.gain.setValueAtTime(0.32, now); ng.gain.exponentialRampToValueAtTime(0.0001, now + 0.22);
                ns.connect(lf); lf.connect(ng); ng.connect(ctx.destination); ns.start(now);
            }
        } catch (e) {}
    }
