            const bGrp = new T.Group(), bBlk = new T.MeshBasicMaterial({ color: 0x030108, transparent: true, opacity: 0.96 }), bAur = warV2EnergyMat(T, '#7c3aed', '#fde047', 7.5, 2.0, 0.95);
