                if (p >= 0.40) { uCor.uOp.value = Math.min(1, (p - 0.40) * 5.0); if (Math.random() < 0.55) { const a = Math.random() * 6.283, r = 1.3 + Math.random() * 1.3; warP({ tex: 'smoke_04', col: '#4c1d95', pos: new T.Vector3(end.x + Math.cos(a) * r, 0.2, end.z + Math.sin(a) * r), vel: new T.Vector3(-Math.cos(a) * 1.3, 2.6, -Math.sin(a) * 1.3), s0: 0.85, s1: 2.0, life: 0.46, op: 0.72, add: false }); } }
                if (p >= 0.62) { bGrp.visible = true; bGrp.rotation.y += 12 * dt; const k = (p - 0.62) / 0.38, s = 0.5 + Math.sin(k * Math.PI) * 0.9; bGrp.scale.set(s, 1, s); if (!umb) { umb = 1; warV2Dome(T, root, end, '#7c3aed', '#fbbf24', 3.4, 0.32); } }
                if (p >= 0.88 && !fin) { fin = 1; warV2Climax(T, root, end, '#7c3aed', '#fbbf24', false); }
