                G.gold = (+G.gold || 0) + bg;
                const els = ['terra', 'agua', 'cristal', 'fogo', 'estelar'], el = els[Math.floor(Math.random() * els.length)];
                const fQty = currentWave >= 10 ? 4 : 2;
                G.frags[el] = (+G.frags[el] || 0) + fQty;
                const mats = ['fiapo', 'garra', 'pedra', 'pata', 'po'], mt = mats[Math.floor(Math.random() * mats.length)];
                G.mats[mt] = (+G.mats[mt] || 0) + 3;
                lines.push(['ph-trophy', '🎁 BAÚ DE MARCO (Onda ' + currentWave + '): +' + bg + ' ouro, +' + fQty + ' frag. ' + el + ', +3 ' + mt]);
                if (currentWave % 10 === 0) {
                    const rk = currentWave >= 20 ? 3 : 2;
                    const sp = warEgg(rk, el, true);
                    if (sp) { z.eggs.push({ sp: sp.id, el: 0, tot: Math.round(ZHATCH[sp.rk] * 0.6), by: [sp.id, sp.id], ln: Date.now() }); lines.push(['ph-egg', 'Ovo de Marco: ' + sp.n + ' (' + ZR[sp.rk].n + ')!']); }
                }
