        const cr = first ? S.crystals : Math.round(S.crystals * 0.25) + (stars > prev ? 10 * (stars - prev) : 0); s.res.c = (+s.res.c || 0) + cr; lines.push(['ph-diamond', cr + ' cristais' + (first ? '' : ' (repetição)')]);
