    /* ===== FORJA DE RUNAS (Etapa 2): espólios + fragmentos viram runas. Runas são DIFÍCEIS de conseguir (material de chefe na receita; fundir 3 em 1). Salvo em z.loot.runes ===== */
    /* 2026-11-17 (Etapa 3): runas viram atributos (vida, dano, essência) e CHANCES de status (congelar, queimar, atordoar). pct = comum/rara/épica. */
    const WAR_RUNES = {
        vida:  { n: 'Runa da Vida',  ic: 'ph-heart',     col: '#7fd24a', el: 'terra',   mat: 'pedra', boss: 'nuc0', pct: [6, 10, 15], eff: v => '+' + v + '% de vida' },
        furia: { n: 'Runa da Fúria', ic: 'ph-sword',     col: '#ff7a3a', el: 'estelar', mat: 'pata',  boss: 'nuc4', pct: [6, 10, 15], eff: v => '+' + v + '% de dano' },
        gelo:  { n: 'Runa do Gelo',  ic: 'ph-snowflake', col: '#6ac8ff', el: 'agua',    mat: 'fiapo', boss: 'nuc1', pct: [8, 12, 18], eff: v => v + '% de chance de congelar o inimigo', st: 1 },
        brasa: { n: 'Runa da Brasa', ic: 'ph-fire',      col: '#ff8a2a', el: 'estelar', mat: 'garra', boss: 'nuc3', pct: [8, 12, 18], eff: v => v + '% de chance de queimar o inimigo', st: 1 },
        raio:  { n: 'Runa do Raio',  ic: 'ph-lightning', col: '#ffd24a', el: 'cristal', mat: 'po',    boss: 'nuc2', pct: [10, 15, 22], eff: v => v + '% de chance de atordoar o inimigo (1,5 s)', st: 1 },
        sorte: { n: 'Runa da Sorte', ic: 'ph-clover',    col: '#7af0b0', el: 'agua',    mat: 'fiapo', boss: 'nuc0', pct: [6, 10, 15], eff: v => '+' + v + '% de essência das esferas' }
    };
    const WAR_RUNE_TIER = ['Comum', 'Rara', 'Épica'];
    const WAR_RUNE_CAP = { vida: 30, furia: 30, sorte: 30, gelo: 40, brasa: 40, raio: 40 };   /* teto somado por dragão */
    const WAR_RUNE_OLD = { perfura: 'raio', carga: 'brasa' };   /* runas da 1ª versão da Forja: viram as novas, 1 por 1 (nada se perde) */
    function warRuneMig(L) {
        try {
            if (Array.isArray(L.runes)) {
                const m = {};
                L.runes.forEach(r => { if (r && r.t) { const k = r.t + ':' + (r.k | 0); m[k] = (m[k] || 0) + 1; } });
                L.runes = m;
            }
            Object.keys(WAR_RUNE_OLD).forEach(o => [0, 1, 2].forEach(k => { const key = o + ':' + k; if (L.runes[key]) { const nk = WAR_RUNE_OLD[o] + ':' + k; L.runes[nk] = (L.runes[nk] || 0) + L.runes[key]; delete L.runes[key]; } }));
            if (!L._shopFix20261121) {
                L._shopFix20261121 = 1;
                L.runes['furia:2'] = (+L.runes['furia:2'] || 0) + 1;
                L.runes['vida:2']  = (+L.runes['vida:2']  || 0) + 1;
                L.runes['gelo:2']  = (+L.runes['gelo:2']  || 0) + 1;
                L.gold = (+L.gold || 0) + 1600;
                setTimeout(() => { try { clSave(true, 'dragons'); clMsg('⚒️ Compensação do bug da Loja: +3 Runas Épicas (Fúria, Vida, Gelo) e +1.600 ouro entregues na Forja!'); } catch (e) {} }, 900);
            }
        } catch (e) {}
    }
    function warSlotsFor(star) { star = star | 0; return star >= 4 ? 3 : star >= 2 ? 2 : 1; }   /* 0-1★ = 1 encaixe, 2-3★ = 2, 4-5★ = 3 */
    function warEq(id) { const L = warLoot(), a = L.eq[id]; return Array.isArray(a) ? a : []; }
    function warRunePct(key, el) { const t = String(key || '').split(':'), R = WAR_RUNES[t[0]]; return R ? R.pct[+t[1] | 0] * (R.el === el ? 1.25 : 1) : 0; }   /* mesmo elemento do dragão = +25% */
    function warRuneStats(id, el) {   /* soma das runas encaixadas no dragão, já com o teto (frações: 0.15 = 15%) */
        const o = { vida: 0, furia: 0, gelo: 0, brasa: 0, raio: 0, sorte: 0 };
        warEq(id).forEach(key => { if (!key) return; const t = key.split(':')[0]; if (o[t] !== undefined) o[t] += warRunePct(key, el); });
        Object.keys(o).forEach(t => { o[t] = Math.min(WAR_RUNE_CAP[t], o[t]) / 100; }); return o;
    }
    function warRuneEquip(id, slot, key) {   /* tira a runa do estoque e encaixa; a que estava lá volta para o estoque */
        const L = warLoot(), z = clZooS(), a = (z.an || []).find(x => x.id === id); if (!a) return false;
        if (slot < 0 || slot >= warSlotsFor(a.star)) return false; if (key && (L.runes[key] || 0) < 1) return false;
        const arr = L.eq[id] = warEq(id).slice(); while (arr.length < 3) arr.push(null);
        if (arr[slot]) L.runes[arr[slot]] = (L.runes[arr[slot]] || 0) + 1;
        if (key) L.runes[key]--; arr[slot] = key || null; clSave(true); CL.ver++; return true;
    }
    function warRuneRecipe(type, k) {   /* receita: tudo que precisa para forjar (k=0) ou fundir (k=1,2) */
        const R = WAR_RUNES[type];
        if (k === 0) return { items: [[R.mat, type === 'sorte' ? 10 : 6], [R.boss, 2]], frag: [R.el, 8], g: 190, runes: null };
        if (k === 1) return { items: [[R.boss, 3]], frag: [R.el, 20], g: 550, runes: [type + ':0', 3] };
        return { items: [[R.boss, 5]], frag: [R.el, 40], g: 1300, runes: [type + ':1', 3] };
    }
    function warForgeLevel() { try { const s = clS(); let lv = 0; (s.pcs || []).forEach(p => { if (p[0] === 'forja') lv = Math.max(lv, (p[4] | 0) || 1); }); return lv; } catch (e) { return 0; } }
    function warRuneCan(type, k) {
        const L = warLoot(), s = clS(), r = warRuneRecipe(type, k), miss = [];
        r.items.forEach(it => { if ((L.mats[it[0]] || 0) < it[1]) miss.push((WAR_MATS[it[0]] || {}).n); });
        if ((L.frag[r.frag[0]] || 0) < r.frag[1]) miss.push('Fragmentos de ' + WAR_FRAGS[r.frag[0]].n);
        if ((+L.gold || 0) < r.g) miss.push('Ouro');
        if (r.runes && (L.runes[r.runes[0]] || 0) < r.runes[1]) miss.push(r.runes[1] + ' runas ' + WAR_RUNE_TIER[k - 1].toLowerCase() + 's');
        return { ok: !miss.length, miss, r };
    }
    function warRuneForge(type, k) {
        if (CL.visit) return { ok: false, err: 'Só na sua colônia.' }; if (!WAR_RUNES[type] || k < 0 || k > 2) return { ok: false, err: 'Runa inválida.' };
        const c = warRuneCan(type, k); if (!c.ok) return { ok: false, err: 'Falta: ' + c.miss.join(', ') + '.' };
        const L = warLoot(), s = clS(), r = c.r;
        r.items.forEach(it => { L.mats[it[0]] -= it[1]; }); L.frag[r.frag[0]] -= r.frag[1]; L.gold = (+L.gold || 0) - r.g; if (r.runes) L.runes[r.runes[0]] -= r.runes[1];
        const key = type + ':' + k; L.runes[key] = (L.runes[key] || 0) + 1; L.made = (L.made || 0) + 1; CL.ver++; try { clSave(true); } catch (e) {}
        return { ok: true, key };
    }
