            + '.wfg-mode{display:flex;gap:8px;margin:0 0 12px}.wfg-mode button{flex:1;min-height:46px;border-radius:14px;border:2px solid #ffffff22;background:#0005;color:#ffe9c9;font:800 16px inherit;font-family:inherit;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer}.wfg-mode button.on{border-color:#ffc24a;background:linear-gradient(#6a3a14,#3a1d0a);color:#ffe08a}.wfg-dg{display:grid;grid-template-columns:repeat(auto-fill,minmax(176px,1fr));gap:10px}.wfg-eq{max-width:780px!important}.wfg-dc{border-radius:16px;padding:10px;background:#0006;border:2px solid #ffffff1c;text-align:center;display:flex;flex-direction:column;align-items:center;gap:2px}.wfg-dc .pt{width:84px;height:84px;display:grid;place-items:center}.wfg-dc .pt img{width:100%;height:100%;object-fit:contain}.wfg-dc b{font-size:15px}.wfg-dc small{font-size:12px;color:#ffd24a;min-height:15px}.wfg-dc .sls{display:flex;gap:6px;margin-top:6px}.wfg-sl{position:relative;width:44px;height:44px;border-radius:14px;border:2px dashed #ffffff40;background:#0006;color:#ffffff90;font-size:20px;display:grid;place-items:center;cursor:pointer;padding:0}.wfg-sl.full{border-style:solid;border-color:var(--tc);background:color-mix(in srgb,var(--tc) 22%,#150d0b);color:var(--tc);font-size:26px}.wfg-sl.on{box-shadow:0 0 0 3px #ffe08a}.wfg-sl.lock{cursor:default;opacity:.35;border-style:solid;border-color:#ffffff22}.wfg-sl em{position:absolute;right:-4px;bottom:-5px;font-style:normal;font-size:10px;font-weight:900;padding:0 4px;border-radius:6px;background:var(--tc);color:#120a08}.wfg-sheet{position:fixed;left:0;right:0;bottom:0;max-height:62%;overflow-y:auto;z-index:5;padding:12px 14px 22px;border-radius:22px 22px 0 0;background:linear-gradient(#3a2012,#1a0e08);border-top:3px solid #ffc24a;box-shadow:0 -10px 30px #000c;display:flex;flex-direction:column;gap:8px}.wfg-sh{display:flex;align-items:center;justify-content:space-between;font-size:18px;color:#ffd98a}.wfg-x.sm{width:38px;height:38px;font-size:18px}.wfg-rl{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:14px;border:2px solid color-mix(in srgb,var(--tc,#fff) 55%,transparent);background:#0006;color:#fff3dd;font-family:inherit;text-align:left;cursor:pointer;min-height:56px}.wfg-rl>i{font-size:30px;color:var(--tc,#ffd98a)}.wfg-rl span{flex:1}.wfg-rl b{display:block;font-size:16px}.wfg-rl small{font-size:13px;opacity:.85}.wfg-rl em{font-style:normal;font-weight:900;font-size:18px;color:var(--tc)}.wfg-rl.off{--tc:#ff9a9a}.wfg-go{width:100%;min-height:50px;border-radius:14px;border:2px solid #ffe08a;background:linear-gradient(#ffc24a,#e8761a);color:#2a1206;font:900 17px inherit;font-family:inherit;cursor:pointer;box-shadow:0 4px 0 #8a3f08}.wfg-go:disabled{filter:grayscale(1) brightness(.7);opacity:.6;box-shadow:none;cursor:not-allowed}.wfg-note{font-size:15px;opacity:.85;margin:0 0 12px}';
