        const L = warLoot(); if (!ZOO.forgeSel || !WAR_RUNES[ZOO.forgeSel]) ZOO.forgeSel = 'vida'; if (!(ZOO.forgeTier >= 0 && ZOO.forgeTier <= 2)) ZOO.forgeTier = 0;
        const sel = ZOO.forgeSel, k = ZOO.forgeTier, R = WAR_RUNES[sel], c = warRuneCan(sel, k), r = c.r, own = t => L.runes[sel + ':' + t] || 0;
        const meta = WAR_RUNE_TIPS[sel] || { short: '', best: '', tip: '' };
