                return '<button type="button" class="wfg-stone-btn' + (t === sel ? ' on' : '') + '" style="--tc:' + q.col + '" data-cl="zoo-forge-sel" data-t="' + t + '" title="' + esc(q.n + ' — ' + (WAR_RUNE_TIPS[t] || {}).short) + '">'
