            if (!m) { m = document.createElement('div'); m.className = 'cl-wfg'; CL.root.appendChild(m); if (!ZOO.modal) { ZOO.modal = 'colony-war'; m._mod = 1; } }   /* com a Forja aberta a colônia não é desenhada por trás (antes, vindo do menu da Arena, o laço dela seguia rodando) */
