                            const sup = (k, v) => { try { return k + '=' + CSS.supports(k, v); } catch (e) { return k + '=erro'; } };
                            const L = ['UA: ' + navigator.userAgent, 'versão: ' + window.__ruaBuild, 'erro abrir: ' + (window.__arenaOpenErr || '-'), 'erros: ' + JSON.stringify(window.__arenaLog || []), 'viewport: ' + innerWidth + 'x' + innerHeight, q('.cl-root'), q('.cl-dg'), q('.dg-top'), q('.dg-main'), q('.dg-grid'), q('.dg-det'), q('.cl-ao'), q('.ao-main'), q('.cl-ah'), sup('inset', '0'), sup('width', 'clamp(1px,2vw,3px)'), sup('padding', 'max(8px,env(safe-area-inset-top))'), sup('grid-template-columns', 'minmax(0,1fr) clamp(300px,32vw,400px)'), 'is=' + (CSS.supports && CSS.supports('selector(:is(a))')), 'simple=' + !!(document.querySelector('.cl-dg') && /modo simples/.test(document.querySelector('.cl-dg').innerText))];
                            const pre = document.createElement('pre'); pre.id = 'arena-diag'; pre.textContent = L.join('\n'); pre.style.cssText = 'position:fixed;left:6px;top:6px;z-index:2147483600;margin:0;padding:8px;background:#000c;color:#9f9;font:11px/1.35 monospace;max-width:96vw;white-space:pre-wrap;pointer-events:none'; document.body.appendChild(pre); try { fetch('http://127.0.0.1:8790/diag', { method: 'POST', mode: 'no-cors', body: L.join('\n') }); } catch (e) {}
