    const clFmt = n => { n = Math.floor(n + 1e-6); return n >= 1e10 ? (n / 1e9).toFixed(1).replace('.', ',') + 'B' : n >= 1e7 ? (n / 1e6).toFixed(1).replace('.', ',') + 'M' : n >= 1e4 ? (n / 1e3).toFixed(1).replace('.', ',') + 'k' : n.toLocaleString('pt-BR'); };
    const clHM = sec => { sec = Math.max(0, Math.floor(sec)); const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60); return h ? h + 'h' + String(m).padStart(2, '0') : m + ' min'; };
    const clRes = k => CLD.RES.find(r => r[0] === k);
