            const rw = q => nm.filter(k => q.rw[k]).map(k => '<span class="cl-co" style="color:' + CLD.RES.find(x => x[0] === k)[3] + '">+' + Math.round(q.rw[k] * mul) + ' ' + rn(k) + '</span>').join('') + (q.rw.ch ? '<span class="cl-co">+' + (q.rw.ch * mul).toFixed(1).replace('.', ',') + ' h de carga</span>' : '') + (q.rw.fr ? '<span class="cl-co">+' + q.rw.fr + ' ✨</span>' : '') + (q.rw.d ? '<span class="cl-co" style="color:#ff7a1a">+' + Math.round(q.rw.d * mul) + ' doces</span>' : '');
            const row = (q, i) => { const pr = clOrdProg(s, q), ready = pr[0] >= q.n; return '<li class="cl-ord' + (q.done ? ' done' : '') + '"><div><b>' + ttl(q) + '</b><small>' + (q.done ? 'Concluída' : q.t === 'deliver' ? 'Você tem ' + clFmt(s.res[q.r]) + ' · só precisa ter, não gasta nada' : pr[0] >= q.n ? 'Pronto: pegue o prêmio' : Math.floor(pr[0]) + ' / ' + q.n) + '</small><div class="cl-rw">' + rw(q) + '</div><u><i style="width:' + clamp(100 * pr[0] / q.n, 0, 100).toFixed(1) + '%"></i></u></div><button type="button" class="cl-mini" data-cl="claim" data-i="' + i + '"' + (q.done || !ready ? ' disabled' : '') + '>' + (q.done ? '✓' : 'Pegar') + '</button></li>'; };
            const hwOn = clEvActive('halloween'), evL = hwOn && o.ed === todayISO() ? o.eq : null, hwt = clHw().tot, msl = hwOn ? clEvMilestones() : [];
            const evHTML = hwOn ? '<h4 class="cl-h4">🎃 Halloween <small>até 2 de novembro</small></h4><p class="cl-lead">Estudar deixa <b>doces</b> espalhados pelo terreno: toque neles para pegar. Gaste nas peças da aba Halloween do menu de construção. Você já pegou <b>' + hwt + '</b> doces no evento.</p><ul class="cl-sks cl-plain">' + (evL ? row(evL, 4) : '') + msl.map((m, i) => '<li class="cl-ord' + (m.done ? ' done' : '') + '"><div><b>' + m.at + ' doces pegos</b><small>' + (m.done ? 'Pego' : Math.min(hwt, m.at) + ' / ' + m.at) + '</small><div class="cl-rw">' + (m.rw.fr ? '<span class="cl-co">+' + m.rw.fr + ' ✨</span>' : '') + (m.rw.ch ? '<span class="cl-co">+' + m.rw.ch + ' h de carga</span>' : '') + (m.rw.c ? '<span class="cl-co" style="color:#5ee0ff">cristal</span>' : '') + '</div><u><i style="width:' + clamp(100 * hwt / m.at, 0, 100).toFixed(1) + '%"></i></u></div><button type="button" class="cl-mini" data-cl="ev-claim" data-i="' + i + '"' + (!m.ready ? ' disabled' : '') + '>' + (m.done ? '✓' : 'Pegar') + '</button></li>').join('') + '</ul>' : '';
            body = '<p class="cl-lead">Quando a barra enche, toque em <b>Pegar</b> para receber o prêmio. Os de estudo só andam quando você estuda de verdade. <b>Sequência: ' + (o.streak || 0) + ' dia' + (o.streak === 1 ? '' : 's') + '</b> (prêmios +' + Math.round((mul - 1) * 100) + '%, até +50%). Falhar um dia só zera a sequência: nada do que você ganhou se perde.</p><h4 class="cl-h4">Hoje</h4><ul class="cl-sks cl-plain">' + o.l.map(row).join('') + '</ul><h4 class="cl-h4">Da semana <small>meta e desafio, calculados pelo seu ritmo dos últimos 14 dias</small></h4><ul class="cl-sks cl-plain">' + row(o.wl, 3) + row(o.wl2, 5) + '</ul>' + evHTML;
