            const ub = el.querySelector('u'), amt = Math.floor(ready.slice().sort((a, b) => b[1] - a[1])[0][1]), tip = info + ' · ' + t.n + '. Toque para coletar só desta peça.', ut = amt > 1 ? clFmt(amt) : ''; el.classList.toggle('multi', ready.length > 1);
