        const F = "'Lilita One','Arial Rounded MT Bold','Chalkboard SE',system-ui,sans-serif", INK = '#2a1405';
        const OUT = (c, w) => '-' + w + 'px -' + w + 'px 0 ' + c + ',' + w + 'px -' + w + 'px 0 ' + c + ',-' + w + 'px ' + w + 'px 0 ' + c + ',' + w + 'px ' + w + 'px 0 ' + c + ',0 ' + (w + 1) + 'px 0 ' + c;
        st.textContent = '.cl-cfg,.cl-cloud{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:60;width:min(540px,94vw);max-height:min(90vh,760px);overflow:auto;overscroll-behavior:contain;border-radius:20px;background:linear-gradient(#4a2d14,#2a170a);border:4px solid #2b1608;box-shadow:inset 0 2px 0 #ffffff33,0 8px 0 #120a04,0 22px 60px #000c;color:#ffeccb;font:500 14px/1.35 system-ui,-apple-system,sans-serif;-webkit-overflow-scrolling:touch}'
