            + '.cf-head b{font:400 26px ' + F + ';color:#ffd44d;text-shadow:' + OUT(INK, 2) + ';letter-spacing:.03em}'
            + '.cf-x{width:44px;height:44px;flex:none;display:grid;place-items:center;cursor:pointer;font:400 20px ' + F + ';color:#ffe9a6;background:linear-gradient(#9b97a8,#5e5a6b);border:3px solid #26222d;border-radius:14px;box-shadow:inset 0 2px 0 #ffffff66,inset 0 -3px 0 #0003,0 3px 0 #17141c;text-shadow:' + OUT('#26222d', 1.5) + '}.cf-x:active{transform:translateY(2px)}'
            + '.cf-body{padding:12px;display:flex;flex-direction:column;gap:12px}'
            + '.cf-sec{padding:10px 12px 12px;border:3px solid #2b1608;border-radius:16px;background:rgba(40,21,9,.82);box-shadow:inset 0 2px 0 #ffffff22,0 3px 0 #00000066}'
            + '.cl-cfg .cf-sec h4,.cl-cloud .cf-sec h4{margin:0 0 8px!important;font:400 22px ' + F + '!important;color:#ffd44d!important;opacity:1!important;text-shadow:' + OUT(INK, 1.5) + '!important;letter-spacing:.03em}'
            + '.cf-sec small{display:block;opacity:.8;font-size:12px;font-weight:500}.cf-note{margin:0 0 8px;font-size:12px;opacity:.75}'
            + '.cf-opt,.cf-act,.cf-chip{display:block;width:100%;margin:6px 0;padding:10px 12px;text-align:left;cursor:pointer;color:#ffe9a6;font:400 16px ' + F + ';letter-spacing:.02em;background:linear-gradient(#9b97a8,#5e5a6b);border:3px solid #26222d;border-radius:14px;box-shadow:inset 0 2px 0 #ffffff66,inset 0 -3px 0 #0003,0 4px 0 #17141c;text-shadow:' + OUT('#26222d', 1.5) + ';touch-action:manipulation}'
            + '.cf-opt small,.cf-act small,.cf-chip small{font:500 12px system-ui,sans-serif;color:#f1e8d4;text-shadow:none;margin-top:2px}'
            + '.cf-opt:active,.cf-act:active,.cf-chip:active{transform:translateY(2px);box-shadow:inset 0 2px 0 #ffffff66,0 2px 0 #17141c}'
