            + '.cf-act.go{background:linear-gradient(#ffe36b,#f29a12);border-color:#6e3508;color:#3a1a05;text-shadow:0 1px 0 #fff8;box-shadow:inset 0 2px 0 #fff9,inset 0 -3px 0 #a5580a66,0 4px 0 #3d1c04}'
            + '.cf-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(138px,1fr));gap:8px}.cf-grid .cf-act,.cf-grid .cf-chip{margin:0;text-align:center}'
