            + '.cl-cloud .cf-sec button{font:400 15px ' + F + '!important;color:#ffe9a6!important;background:linear-gradient(#9b97a8,#5e5a6b)!important;border:3px solid #26222d!important;border-radius:14px!important;padding:9px 12px!important;box-shadow:inset 0 2px 0 #ffffff66,inset 0 -3px 0 #0003,0 4px 0 #17141c!important;text-shadow:' + OUT('#26222d', 1.5) + '!important}'
            + '.cl-cloud .cf-sec button[data-cd="save"]{background:linear-gradient(#ffe36b,#f29a12)!important;border-color:#6e3508!important;color:#3a1a05!important;text-shadow:0 1px 0 #fff8!important}';
