    async function clCloudColonyForRareCheck() {
        const auth = window.ruaAuth, authState = auth && typeof auth.state === 'function' ? auth.state() : null, uid = authState && authState.uid || '';
        if (!uid) return { checked: false, uid: '' }; // sem conta autenticada, não há versão de nuvem para substituir
        let cloud = null;
        if (window.ruaProfile === 'guest') {
            if (!auth || typeof auth.colonyBackups !== 'function') throw new Error('A consulta da conta não está disponível.');
            const backups = await auth.colonyBackups();
            if ((auth.state()?.uid || '') !== uid) throw new Error('A conta mudou durante a consulta.');
            const current = backups.find(x => x.kind === 'nuvem atual');
            if (current) cloud = JSON.parse(current.json);
        } else {
            if (typeof firebase === 'undefined' || !firebase.firestore) throw new Error('A consulta da nuvem não está disponível.');
            const snap = await firebase.firestore().collection('workspaces').doc('cestille_hub').get({ source: 'server' });
            if ((auth.state()?.uid || '') !== uid) throw new Error('A conta mudou durante a consulta.');
            if (snap && snap.exists) {
                const data = window.ruaFs?.dec ? window.ruaFs.dec(snap.data()) : snap.data();
                cloud = data?.ruaLayout?.orbitGame?.colony || null;
            }
        }
        return { checked: true, uid, col: cloud };
    }
    function clRareProgressMissing(local, cloud) {
        if (!local || !cloud) return [];
        const read = col => {
            const out = new Map(), add = (item, kind) => {
                const id = String(item?.sp || ''), species = id && zsp(id), rank = species?.rk | 0;
                if (!id || rank < 3) return;
                const key = kind + ':' + id, value = out.get(key) || { id, rank, name: species?.n || id, count: 0, maxLevel: 0 };
                value.count++; value.maxLevel = Math.max(value.maxLevel, kind === 'adult' ? (zAL(item) || 1) : 0); out.set(key, value);
            };
            (col.zoo?.an || []).forEach(x => add(x, 'adult'));
            (col.zoo?.eggs || []).forEach(x => add(x, 'egg'));
            return out;
        };
        const have = read(local), remote = read(cloud), missing = [];
        const amount = (n, one, many) => n + ' ' + (n === 1 ? one : many);
        for (const [key, r] of remote) {
            const l = have.get(key) || { count: 0, maxLevel: 0 };
            if (l.count < r.count) missing.push({ rank: r.rank, text: r.name + ' — ' + amount(r.count, key.startsWith('egg:') ? 'ovo' : 'dragão', key.startsWith('egg:') ? 'ovos' : 'dragões') + ' na nuvem, ' + amount(l.count, key.startsWith('egg:') ? 'ovo' : 'dragão', key.startsWith('egg:') ? 'ovos' : 'dragões') + ' nesta versão.' });
            else if (key.startsWith('adult:') && l.maxLevel < r.maxLevel) missing.push({ rank: r.rank, text: r.name + ' — nível máximo nv' + r.maxLevel + ' na nuvem, nv' + l.maxLevel + ' nesta versão.' });
        }
        return missing.sort((a, b) => b.rank - a.rank || a.text.localeCompare(b.text, 'pt-BR'));
    }
    function clConfirmRareOverwrite(missing, action) {
        if (!missing.length) return Promise.resolve(true);
        const box = document.createElement('div');
        box.style.cssText = 'position:absolute;inset:0;z-index:120;display:grid;place-items:center;padding:16px;background:rgba(3,4,12,.82);backdrop-filter:blur(5px);color:#f7f1ff;font:500 14px Barlow,system-ui,sans-serif';
        box.innerHTML = '<section role="alertdialog" aria-modal="true" aria-labelledby="cl-rare-warning-title" style="width:min(520px,100%);max-height:88%;overflow:auto;padding:20px;border:1px solid #f4c95d99;border-radius:18px;background:linear-gradient(160deg,#241a34,#100d19);box-shadow:0 20px 70px #000c">'
            + '<h3 id="cl-rare-warning-title" style="margin:0 0 10px;color:#ffdb79">⚠️ A nuvem tem dragões raros que faltam</h3>'
            + '<p style="margin:0 0 10px">A versão que você vai ' + esc(action) + ' não contém todos os dragões Épicos ou Lendários atualmente salvos na nuvem:</p>'
            + '<ul style="margin:0 0 12px;padding-left:22px;line-height:1.6;color:#fff0c2">' + missing.map(x => '<li>' + esc(x.text) + '</li>').join('') + '</ul>'
            + '<p style="margin:0 0 16px;opacity:.9">Se continuar, esta versão substituirá a principal na nuvem. Confira se é isso mesmo.</p>'
            + '<div style="display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px"><button type="button" data-cl-rare-cancel style="padding:10px 14px;border:1px solid #8ad9bb88;border-radius:10px;background:#18372f;color:#d8ffef;font-weight:700;cursor:pointer">Manter a nuvem</button><button type="button" data-cl-rare-confirm style="padding:10px 14px;border:1px solid #f4c95d88;border-radius:10px;background:#5a3820;color:#fff0c2;font-weight:700;cursor:pointer">Continuar e substituir</button></div></section>';
        CL.root.appendChild(box);
        return new Promise(resolve => {
            const finish = value => { box.remove(); resolve(value); };
            box.addEventListener('click', e => { if (e.target === box || e.target.closest('[data-cl-rare-cancel]')) finish(false); else if (e.target.closest('[data-cl-rare-confirm]')) finish(true); e.stopPropagation(); });
            box.addEventListener('keydown', e => { if (e.key === 'Escape') { e.preventDefault(); finish(false); } });
            box.querySelector('[data-cl-rare-cancel]')?.focus();
        });
    }
    async function clApplyRestoredColony(col, okMsg, action) {
        if (!col || !Array.isArray(col.pcs)) return false;
        let review;
        try {
            review = await clCloudColonyForRareCheck();
            if (review.checked) {
                const missing = clRareProgressMissing(col, review.col);
                if (missing.length && !await clConfirmRareOverwrite(missing, action || 'restaurar')) return false;
                if ((window.ruaAuth?.state?.().uid || '') !== review.uid) { clMsg('A conta mudou. Nada foi substituído; abra a ação novamente.', true); return false; }
            }
        } catch (err) {
            clMsg('Não consegui conferir a nuvem agora. Nada foi substituído; tente de novo quando a conexão voltar.', true);
            return false;
        }
        const g0 = G(), cur = clS();
        if (col !== cur) {
            try { window.ruaColonySave?.checkpoint(cur, 'before-restore'); } catch (e) {}
            if (cur && Array.isArray(cur.pcs)) g0.colonyBk = [{ at: Date.now(), n: cur.pcs.length, nuc: cur.nuc || 1, json: JSON.stringify(cur) }].concat(g0.colonyBk || []).slice(0, 6);
            col._save = cur._save;
            col.t = Date.now();   // evita que restaurar backup antigo adiante ovos e produção pelo tempo desde o backup
        }
        col.u = Date.now(); g0.colony = col; CL.sref = null; CL.ver++; CL3.need = true; CL.sel = -1; ZOO.sig = '';
        const restoreMeta = review?.checked && review.col ? { restoreOf: review.col._save?.id || '', restoreCommit: review.col._save?.commit || '' } : null;
        clSave(true, 'restore', restoreMeta); clUiPaint(true);
        try { if (CL.ui && CL.ui.panelOpen()) clPanel(); } catch (e) {}
        const restoreId = clS()._save?.id || '';
        const ok = window.ruaProfile === 'guest'
            ? await (window.ruaForcePush?.() || Promise.resolve(false))
            : await Promise.resolve(typeof saveState === 'function' ? saveState(false) : false).then(v => v !== false, () => false);
        try { clHistPush('pin'); } catch (e) {}
        if (!ok) { clMsg((okMsg || 'Versão recuperada') + ' foi mantida neste aparelho, mas a nuvem não confirmou a gravação.', true); return false; }
        if (review?.checked) {
            try {
                const latest = await clCloudColonyForRareCheck();
                if (!latest.checked || latest.uid !== review.uid || latest.col?._save?.id !== restoreId) {
                    clMsg('A nuvem manteve outra versão. A cópia que você escolheu ficou neste aparelho em Recuperar progresso; nada foi confirmado como principal.', true);
                    return false;
                }
            } catch (err) {
                clMsg('A gravação foi enviada, mas não consegui confirmar a nuvem. A cópia escolhida continua em Recuperar progresso; não atualize ainda.', true);
                return false;
            }
        }
        clMsg((okMsg || 'Versão recuperada') + ' Confirmada como principal na nuvem.');
        return true;
    }

